const L=typeof input.l==='string'?JSON.parse(input.l):(input.l||[]);
const keys=L.length?Object.keys(L[0]):[];
const st={};for(const x of L){st[x.status]=(st[x.status]||0)+1;}
const sample=L.slice(0,2);
const rows=L.map(x=>{const o={p:x.displayPhone,s:x.status};for(const k of Object.keys(x)){if(/follow|agent|assign|rep|owner|user/i.test(k)){o[k]=x[k];}}o.a=x.audience;o.c=String(x.createDate||x.createdAt||'').slice(0,16);return o;});
return JSON.stringify({n:L.length,keys,st,sample,rows});
